CREATE TABLE IF NOT EXISTS nicar."ContratoColaborador" (
 "IdContrato" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 "IdUsuario" integer NOT NULL REFERENCES nicar."Usuario"("IdUsuario"),
 "NumeroContrato" varchar(60) NOT NULL UNIQUE,
 "TipoContrato" varchar(30) NOT NULL CHECK ("TipoContrato" IN ('Indefinido','Plazo fijo','Proyecto')),
 "Cargo" varchar(100) NOT NULL, "FechaInicio" date NOT NULL, "FechaFin" date,
 "SalarioBaseNIO" numeric(12,2) NOT NULL CHECK ("SalarioBaseNIO">0),
 "Observaciones" varchar(500), "Estado" varchar(20) NOT NULL DEFAULT 'Activo' CHECK ("Estado" IN ('Activo','Finalizado','Cancelado')),
 "Activo" boolean NOT NULL DEFAULT true, "FechaRegistro" timestamptz NOT NULL DEFAULT now(),
 CHECK ("FechaFin" IS NULL OR "FechaFin">="FechaInicio")
);
CREATE UNIQUE INDEX IF NOT EXISTS "ContratoColaborador_activo_unico_idx" ON nicar."ContratoColaborador"("IdUsuario") WHERE "Activo" AND "Estado"='Activo';
CREATE TABLE IF NOT EXISTS nicar."PagoColaborador" (
 "IdPagoColaborador" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 "IdUsuario" integer NOT NULL REFERENCES nicar."Usuario"("IdUsuario"),
 "IdContrato" integer NOT NULL REFERENCES nicar."ContratoColaborador"("IdContrato"),
 "TipoPago" varchar(20) NOT NULL CHECK ("TipoPago" IN ('Salario','Comision')),
 "Periodo" char(7) NOT NULL CHECK ("Periodo" ~ '^[0-9]{4}-(0[1-9]|1[0-2])$'),
 "FechaPago" date NOT NULL, "MontoBrutoNIO" numeric(12,2) NOT NULL CHECK ("MontoBrutoNIO">0),
 "DeduccionINSSNIO" numeric(12,2) NOT NULL DEFAULT 0 CHECK ("DeduccionINSSNIO">=0),
 "AhorroAutorizadoNIO" numeric(12,2) NOT NULL DEFAULT 0 CHECK ("AhorroAutorizadoNIO">=0),
 "RetencionIRNIO" numeric(12,2) NOT NULL DEFAULT 0 CHECK ("RetencionIRNIO">=0),
 "OtrasDeduccionesNIO" numeric(12,2) NOT NULL DEFAULT 0 CHECK ("OtrasDeduccionesNIO">=0),
 "MontoNetoNIO" numeric(12,2) NOT NULL CHECK ("MontoNetoNIO">=0),
 "ComisionUSD" numeric(12,2), "TasaCambio" numeric(12,6) NOT NULL DEFAULT 1 CHECK ("TasaCambio">0),
 "MetodoPagoColaborador" varchar(20) NOT NULL CHECK ("MetodoPagoColaborador" IN ('Transferencia','Efectivo','Cheque')),
 "Referencia" varchar(100) NOT NULL, "RegistradoPor" integer NOT NULL REFERENCES nicar."Usuario"("IdUsuario"),
 "Estado" varchar(20) NOT NULL DEFAULT 'Registrado' CHECK ("Estado" IN ('Registrado','Anulado')),
 "FechaRegistro" timestamptz NOT NULL DEFAULT now(),
 CHECK ("MontoNetoNIO"="MontoBrutoNIO"-"DeduccionINSSNIO"-"AhorroAutorizadoNIO"-"RetencionIRNIO"-"OtrasDeduccionesNIO"),
 CHECK (("TipoPago"='Comision' AND "ComisionUSD">0) OR ("TipoPago"='Salario' AND "ComisionUSD" IS NULL))
);
CREATE UNIQUE INDEX IF NOT EXISTS "PagoColaborador_periodo_unico_idx" ON nicar."PagoColaborador"("IdUsuario","TipoPago","Periodo") WHERE "Estado"='Registrado';
CREATE INDEX IF NOT EXISTS "PagoColaborador_fecha_idx" ON nicar."PagoColaborador"("FechaPago","IdUsuario");
REVOKE ALL ON nicar."ContratoColaborador",nicar."PagoColaborador" FROM PUBLIC,anon,authenticated;
GRANT SELECT,INSERT,UPDATE,DELETE ON nicar."ContratoColaborador",nicar."PagoColaborador" TO postgres;
GRANT USAGE,SELECT ON ALL SEQUENCES IN SCHEMA nicar TO postgres;
